<?php

namespace Database\Seeders;

use App\Models\Listing;
use Illuminate\Database\Seeder;

/**
 * Seeds the demo job board with readable English listings.
 *
 * The original demo rows were generated by Faker and contained Latin filler
 * text. This seeder replaces those rows (by position) with realistic English
 * job posts, and creates them when the table is empty.
 */
class EnglishListingsSeeder extends Seeder
{
    /**
     * Run the database seeds.
     *
     * @return void
     */
    public function run()
    {
        $existingIds = Listing::orderBy('id')->pluck('id')->all();

        foreach ($this->listings() as $index => $listing) {
            $attributes = array_merge($listing, [
                'user_id' => 1,
                'logo' => null,
            ]);

            if (isset($existingIds[$index])) {
                Listing::whereKey($existingIds[$index])->update($attributes);
            } else {
                Listing::create($attributes);
            }
        }
    }

